using System.Collections.Concurrent;using AfriWallet.Merchants.Settlement.Application.Abstractions;using AfriWallet.Merchants.Settlement.Domain.Settlements;namespace AfriWallet.Merchants.Settlement.Infrastructure;
public sealed class SandboxCaptureEligibleDecisionReader:ICaptureEligibleDecisionReader{private readonly Dictionary<Guid,CaptureEligibleDecisionSnapshot> _items=new();public void Set(CaptureEligibleDecisionSnapshot s)=>_items[s.DecisionId]=s;public Task<CaptureEligibleDecisionSnapshot?> GetAsync(Guid id,CancellationToken ct=default){ct.ThrowIfCancellationRequested();_items.TryGetValue(id,out var r);return Task.FromResult(r);}}
public sealed class SandboxMerchantSettlementProvider:IMerchantSettlementProvider{private readonly Queue<MerchantSettlementProviderStatus> _behaviors=new();public void Enqueue(MerchantSettlementProviderStatus s)=>_behaviors.Enqueue(s);public Task<MerchantSettlementProviderResult> SubmitAsync(MerchantSettlementProviderRequest r,CancellationToken ct=default){ct.ThrowIfCancellationRequested();var s=_behaviors.Count>0?_behaviors.Dequeue():MerchantSettlementProviderStatus.Accepted;var reference=s is MerchantSettlementProviderStatus.Accepted or MerchantSettlementProviderStatus.PartialFailure?$"SANDBOX-MST-{r.SettlementId:N}":null;return Task.FromResult(new MerchantSettlementProviderResult(s,reference,$"Sandbox settlement provider result: {s}"));}public Task<bool> CompensateAsync(string r,CancellationToken ct=default){ct.ThrowIfCancellationRequested();return Task.FromResult(!string.IsNullOrWhiteSpace(r));}}
public sealed class InMemoryMerchantSettlementRepository:IMerchantSettlementRepository{private readonly ConcurrentDictionary<Guid,MerchantSettlementOrchestration> _items=new();public Task AddAsync(MerchantSettlementOrchestration s,CancellationToken ct=default){if(!_items.TryAdd(s.SettlementId,s))throw new InvalidOperationException("Settlement orchestration already exists.");return Task.CompletedTask;}public Task SaveAsync(MerchantSettlementOrchestration s,CancellationToken ct=default){_items[s.SettlementId]=s;return Task.CompletedTask;}public Task<MerchantSettlementOrchestration?> GetAsync(Guid id,CancellationToken ct=default){_items.TryGetValue(id,out var r);return Task.FromResult(r);}public Task<MerchantSettlementOrchestration?> GetByDecisionAsync(Guid id,CancellationToken ct=default)=>Task.FromResult(_items.Values.FirstOrDefault(x=>x.PaymentDecisionId==id));public Task<MerchantSettlementOrchestration?> GetByIdempotencyKeyAsync(string k,CancellationToken ct=default)=>Task.FromResult(_items.Values.FirstOrDefault(x=>string.Equals(x.IdempotencyKey,k,StringComparison.Ordinal)));}
public sealed class InMemoryMerchantSettlementAuditStore:IMerchantSettlementAuditStore{private readonly ConcurrentQueue<MerchantSettlementAuditEvent> _events=new();public Task AppendAsync(MerchantSettlementAuditEvent e,CancellationToken ct=default){_events.Enqueue(e);return Task.CompletedTask;}public Task<IReadOnlyCollection<MerchantSettlementAuditEvent>> GetAsync(Guid id,CancellationToken ct=default){IReadOnlyCollection<MerchantSettlementAuditEvent> r=_events.Where(x=>x.SettlementId==id).ToArray();return Task.FromResult(r);}}public sealed class SystemMerchantSettlementClock:IMerchantSettlementClock{public DateTimeOffset UtcNow=>DateTimeOffset.UtcNow;}
